// Package emit prints lowered Go syntax trees and builds source maps.
//
// Printing uses go/printer with gofmt's configuration. The printed text is
// reparsed and walked in lockstep with the lowered tree to record, for every
// node that carries a Lyth span, the exact generated byte range (an exact
// source map). Column-less //line directives are then inserted so the Go
// toolchain, runtime stack traces, and debuggers report Lyth file and line.
package emit

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/lyth-lang/lyth/internal/lower"
	"github.com/lyth-lang/lyth/internal/source"
)

// Options controls emission.
type Options struct {
	LineDirectives bool
	AbsPaths       bool // absolute Lyth paths in //line directives (overlay builds)
	// DenseLines puts a directive wherever the Lyth line changes, not only
	// before lines that can fail, so that debuggers, profilers, and vet see
	// the exact Lyth line of every statement. Builds use it; lyth gen keeps
	// the sparse form, which is easier to read.
	DenseLines bool
}

// Segment maps a generated byte range to a Lyth span.
type Segment struct {
	GenStart, GenEnd int
	Src              source.Span
	Synthetic        bool
}

// SourceMap maps one generated file back to Lyth source.
type SourceMap struct {
	GenName  string
	Src      *source.File
	Segments []Segment // sorted by GenStart, longer first on ties
	// LineToSrc maps 1-based generated lines to 1-based Lyth lines (0: none).
	LineToSrc []int
}

// Result is an emitted Go file.
type Result struct {
	Name string
	Code []byte
	Map  *SourceMap
}

// Emit prints a lowered file.
func Emit(f *lower.File, opts Options) (*Result, error) {
	var body bytes.Buffer
	placeSentinels(f.AST)
	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	if err := cfg.Fprint(&body, f.Fset, f.AST); err != nil {
		return nil, fmt.Errorf("printing %s: %w", f.GoName, err)
	}
	printed := body.Bytes()

	fset2 := token.NewFileSet()
	f2, err := parser.ParseFile(fset2, f.GoName, printed, parser.ParseComments|parser.SkipObjectResolution)
	if err != nil {
		return nil, fmt.Errorf("internal error: generated code for %s does not parse: %v\n%s", f.Src.Name, err, printed)
	}
	tf := fset2.File(f2.Pos())
	// go/printer keeps a blank line wherever positions leave a gap. Gaps
	// right after an opening brace or before a closing one come from
	// lowering (a returned when's first branch lies below the return), and
	// idiomatic Go has none, so they are removed before mapping.
	if trimmed := trimBlockEdges(printed, f2, tf); len(trimmed) != len(printed) {
		printed = trimmed
		fset2 = token.NewFileSet()
		if f2, err = parser.ParseFile(fset2, f.GoName, printed, parser.ParseComments|parser.SkipObjectResolution); err != nil {
			return nil, fmt.Errorf("internal error: trimmed code for %s does not parse: %v\n%s", f.Src.Name, err, printed)
		}
		tf = fset2.File(f2.Pos())
	}

	built := preorder(f.AST)
	reparsed := preorder(f2)
	for i := 0; i < len(built) || i < len(reparsed); i++ {
		if i >= len(built) || i >= len(reparsed) || reflect.TypeOf(built[i]) != reflect.TypeOf(reparsed[i]) {
			ctx := ""
			if i < len(reparsed) {
				p := tf.Position(reparsed[i].Pos())
				lines := strings.Split(string(printed), "\n")
				if p.Line >= 1 && p.Line <= len(lines) {
					ctx = fmt.Sprintf(" near generated line %d: %s", p.Line, strings.TrimSpace(lines[p.Line-1]))
				}
			}
			var bt, rt any = "end", "end"
			if i < len(built) {
				bt = reflect.TypeOf(built[i])
			}
			if i < len(reparsed) {
				rt = reflect.TypeOf(reparsed[i])
			}
			return nil, fmt.Errorf("internal error: generated tree for %s changed shape when printed at node %d (%v vs %v)%s", f.Src.Name, i, bt, rt, ctx)
		}
	}
	if len(f.Comments) > 0 {
		// Comments inside function bodies go next to the code of their
		// Lyth lines; the tree keeps its shape, so only the text changes.
		if commented, ok := placeComments(printed, f, built, reparsed, tf); ok {
			fset3 := token.NewFileSet()
			if f3, err := parser.ParseFile(fset3, f.GoName, commented, parser.ParseComments|parser.SkipObjectResolution); err == nil {
				if r3 := preorder(f3); len(r3) == len(reparsed) {
					printed, f2, tf, reparsed = commented, f3, fset3.File(f3.Pos()), r3
				}
			}
		}
	}
	var segs []Segment
	segNode := map[int]ast.Node{} // reparsed node of each segment, by GenStart
	for i, n := range built {
		span, ok := f.Spans[n]
		if !ok {
			continue
		}
		r := reparsed[i]
		if !r.Pos().IsValid() || !r.End().IsValid() {
			continue
		}
		segs = append(segs, Segment{GenStart: tf.Offset(r.Pos()), GenEnd: tf.Offset(r.End()), Src: span, Synthetic: f.Synthetic[n]})
		if _, seen := segNode[tf.Offset(r.Pos())]; !seen {
			segNode[tf.Offset(r.Pos())] = r
		}
	}

	// Lines inside multi-line string literals cannot take directives.
	forbidden := map[int]bool{}
	ast.Inspect(f2, func(n ast.Node) bool {
		if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
			a, b := tf.Line(lit.Pos()), tf.Line(lit.End())
			for l := a + 1; l <= b; l++ {
				forbidden[l] = true
			}
		}
		return true
	})

	// Top-level declarations are separated by a blank line (go/printer
	// cannot know the layout of synthesized declarations).
	// Declarations adjacent in the Lyth source stay adjacent (gofmt aligns
	// consecutive one-line functions); blank lines are added only after the
	// import block, around compiler-synthesized declarations, and where the
	// Lyth source has a gap.
	blankBefore := map[int]bool{}
	// docOf returns the first line of declaration i's doc comment. The
	// lowered tree knows the doc even where Go's parser takes it for the
	// line comment of the declaration above (const x = 1 // note).
	docOf := func(i int) (start int, ok bool) {
		var doc, built *ast.CommentGroup
		switch d := f2.Decls[i].(type) {
		case *ast.FuncDecl:
			doc = d.Doc
		case *ast.GenDecl:
			doc = d.Doc
		}
		if doc != nil {
			return tf.Line(doc.Pos()), true
		}
		switch d := f.AST.Decls[i].(type) {
		case *ast.FuncDecl:
			built = d.Doc
		case *ast.GenDecl:
			built = d.Doc
		}
		if built == nil || len(built.List) == 0 {
			return tf.Line(f2.Decls[i].Pos()), false
		}
		return tf.Line(f2.Decls[i].Pos()) - len(built.List), true
	}
	// A declaration that gofmt sees with a doc comment needs a blank line
	// before it; a //line directive inserted right above a declaration is
	// such a comment too, so those lines are remembered here.
	undocumented := map[int]bool{}
	if len(f2.Decls) > 0 {
		// gofmt separates the package clause from the first declaration.
		if start, _ := docOf(0); start == tf.Line(f2.Name.End())+1 {
			blankBefore[start] = true
		}
	}
	for i := 1; i < len(f2.Decls); i++ {
		prevEnd := tf.Line(f2.Decls[i-1].End())
		start, hasDoc := docOf(i)
		if start != prevEnd+1 {
			continue
		}
		if hasDoc {
			blankBefore[start] = true
			continue
		}
		undocumented[start] = true
		prevSpan, prevOK := f.Spans[f.AST.Decls[i-1]]
		curSpan, curOK := f.Spans[f.AST.Decls[i]]
		isImport := false
		if gd, ok := f2.Decls[i-1].(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			isImport = true
		}
		gap := prevOK && curOK && curSpan.StartPos().Line > prevSpan.EndPos().Line+1
		if isImport || !prevOK || !curOK || f.Synthetic[f.AST.Decls[i]] || f.Synthetic[f.AST.Decls[i-1]] || gap {
			blankBefore[start] = true
		}
	}

	// Lyth line for each generated line: the first mapped node starting on it.
	lineCount := tf.LineCount()
	// Lines whose first mapped node is compiler glue (error checks, guarded
	// unboxing) get no directive of their own: glue cannot fail at run time,
	// so drifting line numbers there cost nothing, while every line that
	// starts with user code is attributed exactly.
	lineSrc := make([]int, lineCount+2)
	lineSynth := make([]bool, lineCount+2)
	order := make([]Segment, len(segs))
	copy(order, segs)
	sort.SliceStable(order, func(i, j int) bool { return order[i].GenStart < order[j].GenStart })
	lineNode := make([]ast.Node, lineCount+2)
	for _, s := range order {
		gl := tf.Line(tf.Pos(s.GenStart))
		if lineSrc[gl] == 0 && s.Src.File == f.Src {
			lineSrc[gl] = s.Src.StartPos().Line
			lineSynth[gl] = s.Synthetic
			lineNode[gl] = segNode[s.GenStart]
		}
	}
	// Lines whose statement cannot fail at run time (assignments of
	// literals, branches, plain comparisons) need no directive either.
	// Glue that can fail (a call hoisted out of an expression, the panic of
	// !!) does need one: a stack trace must show the Lyth line it came from.
	quiet := map[int]bool{}
	ast.Inspect(f2, func(n ast.Node) bool {
		if st, ok := n.(ast.Stmt); ok {
			if _, isBlock := st.(*ast.BlockStmt); !isBlock {
				if !stmtMayFail(st) {
					quiet[tf.Line(st.Pos())] = true
				} else if l := tf.Line(st.Pos()); l < len(lineSynth) && lineSrc[l] != 0 && hoisted(st) {
					lineSynth[l] = false
				}
			}
		}
		return true
	})
	// So do continuation lines of a multi-line statement (a field of a
	// composite literal, an argument) whose expression cannot fail.
	for l, n := range lineNode {
		if e, ok := n.(ast.Expr); ok && !exprMayFail(e) {
			quiet[l] = true
		}
	}
	for l := range quiet {
		if l < len(lineSynth) {
			lineSynth[l] = true
		}
	}

	// A directive for a declaration with a doc comment goes between the
	// comment and the declaration, after an empty "//" line: the canonical
	// form gofmt gives directives in doc comments.
	docBefore := map[int]bool{}
	for i, d := range f2.Decls {
		var doc *ast.CommentGroup
		switch d := d.(type) {
		case *ast.FuncDecl:
			doc = d.Doc
		case *ast.GenDecl:
			doc = d.Doc
		}
		if doc == nil {
			switch b := f.AST.Decls[i].(type) {
			case *ast.FuncDecl:
				doc = b.Doc
			case *ast.GenDecl:
				doc = b.Doc
			}
			if doc != nil && len(doc.List) > 0 && !isDirective(doc.List[len(doc.List)-1].Text) {
				docBefore[tf.Line(d.Pos())] = true
			}
			continue
		}
		// A doc comment that ends in directives (//go:embed) has its "//"
		// line already, or needs none when it holds only directives.
		if doc != nil && tf.Line(doc.End())+1 == tf.Line(d.Pos()) && !isDirective(doc.List[len(doc.List)-1].Text) {
			docBefore[tf.Line(d.Pos())] = true
		}
	}

	// Insert //line directives.
	header := fmt.Sprintf("// Code generated by lyth from %s. DO NOT EDIT.\n\n", f.Src.Base())
	if f.Build != "" {
		header += f.Build + "\n\n"
	}
	path := f.Src.Base()
	if opts.AbsPaths {
		path = f.Src.Path
	}
	lines := bytes.SplitAfter(printed, []byte("\n"))
	var out bytes.Buffer
	out.WriteString(header)
	shift := make([]int, lineCount+2) // bytes inserted before each generated line (1-based)
	inserted := len(header)
	implied := 0 // line Go assigns to the next generated line, 0 before any directive
	finalLineSrc := []int{0}
	for i := range header {
		if header[i] == '\n' {
			finalLineSrc = append(finalLineSrc, 0)
		}
	}
	// Inside function bodies, keep a blank line only where the Lyth source has
	// one between the two statements. go/printer adds one wherever positions
	// leave a gap, as after the error check of a call spanning several Lyth
	// lines.
	inBody := map[int]bool{}
	ast.Inspect(f2, func(n ast.Node) bool {
		var body *ast.BlockStmt
		switch n := n.(type) {
		case *ast.FuncDecl:
			body = n.Body
		case *ast.FuncLit:
			body = n.Body
		}
		if body != nil {
			for l := tf.Line(body.Lbrace) + 1; l < tf.Line(body.Rbrace); l++ {
				inBody[l] = true
			}
		}
		return true
	})
	srcAt := func(g, step int) int {
		for ; g >= 1 && g < len(lineSrc); g += step {
			if lineSrc[g] != 0 {
				return lineSrc[g]
			}
		}
		return 0
	}
	unjustified := func(g int) bool {
		if !inBody[g] || forbidden[g] || len(bytes.TrimSpace(lines[g-1])) != 0 {
			return false
		}
		prev, next := srcAt(g-1, -1), srcAt(g+1, 1)
		if prev == 0 || next == 0 {
			return false
		}
		for l := prev + 1; l < next; l++ {
			if f.Src.LineBlank(l) {
				return false
			}
		}
		return true
	}
	for idx, ln := range lines {
		g := idx + 1
		if unjustified(g) {
			inserted -= len(ln)
			if g < len(shift) {
				shift[g] = inserted
			}
			continue
		}
		if blankBefore[g] {
			out.WriteString("\n")
			inserted++
			finalLineSrc = append(finalLineSrc, 0)
			if implied != 0 {
				implied++
			}
		}
		if opts.LineDirectives && g < len(lineSrc) && lineSrc[g] != 0 && !forbidden[g] && implied != lineSrc[g] && (opts.DenseLines || !lineSynth[g] || implied == 0) {
			if undocumented[g] && !blankBefore[g] {
				// The directive becomes the declaration's doc comment.
				out.WriteString("\n")
				inserted++
				finalLineSrc = append(finalLineSrc, 0)
				if implied != 0 {
					implied++
				}
			}
			if docBefore[g] {
				out.WriteString("//\n")
				inserted += 3
				finalLineSrc = append(finalLineSrc, 0)
				if implied != 0 {
					implied++
				}
			}
			d := "//line " + path + ":" + strconv.Itoa(lineSrc[g]) + "\n"
			out.WriteString(d)
			inserted += len(d)
			implied = lineSrc[g]
			finalLineSrc = append(finalLineSrc, 0)
		}
		if g < len(shift) {
			shift[g] = inserted
		}
		out.Write(ln)
		src := 0
		if g < len(lineSrc) {
			src = lineSrc[g]
		}
		finalLineSrc = append(finalLineSrc, src)
		if implied != 0 {
			implied++
		}
	}
	for i := range segs {
		gl := tf.Line(tf.Pos(segs[i].GenStart))
		segs[i].GenStart += shift[gl]
		el := tf.Line(tf.Pos(min(segs[i].GenEnd, tf.Size())))
		segs[i].GenEnd += shift[el]
	}
	sort.SliceStable(segs, func(i, j int) bool {
		if segs[i].GenStart != segs[j].GenStart {
			return segs[i].GenStart < segs[j].GenStart
		}
		return segs[i].GenEnd > segs[j].GenEnd
	})
	return &Result{Name: f.GoName, Code: out.Bytes(), Map: &SourceMap{GenName: f.GoName, Src: f.Src, Segments: segs, LineToSrc: finalLineSrc}}, nil
}

// placeComments inserts the comments of function bodies into the printed
// file: a comment after code goes at the end of the first generated line of
// its Lyth line, and one on its own line before the generated code of the
// next Lyth line of its block (or after the statement it follows, at the
// end of a block). The result is formatted as gofmt does.
func placeComments(printed []byte, f *lower.File, built, reparsed []ast.Node, tf *token.File) ([]byte, bool) {
	firstGen := map[int]int{} // Lyth line -> first generated line of code starting on it
	startGen := map[source.Span]int{}
	endGen := map[source.Span]int{}
	for i, n := range built {
		span, ok := f.Spans[n]
		if !ok || span.File != f.Src {
			continue
		}
		r := reparsed[i]
		if !r.Pos().IsValid() || !r.End().IsValid() {
			continue
		}
		a, b := tf.Line(r.Pos()), tf.Line(r.End())
		if g, ok := firstGen[span.StartPos().Line]; !ok || a < g {
			firstGen[span.StartPos().Line] = a
		}
		if g, ok := startGen[span]; !ok || a < g {
			startGen[span] = a
		}
		endGen[span] = max(endGen[span], b)
	}
	inString := map[int]bool{} // lines continuing a multi-line string literal
	ast.Inspect(reparsed[0], func(n ast.Node) bool {
		if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
			for l := tf.Line(lit.Pos()) + 1; l <= tf.Line(lit.End()); l++ {
				inString[l] = true
			}
		}
		return true
	})
	lines := strings.SplitAfter(string(printed), "\n")
	indent := func(g int) string {
		ln := lines[g-1]
		return ln[:len(ln)-len(strings.TrimLeft(ln, " \t"))]
	}
	// A declaration's or field's doc comment starts above its first line.
	docStart := map[int]int{}
	ast.Inspect(reparsed[0], func(n ast.Node) bool {
		var doc *ast.CommentGroup
		switch n := n.(type) {
		case *ast.FuncDecl:
			doc = n.Doc
		case *ast.GenDecl:
			doc = n.Doc
		case *ast.Field:
			doc = n.Doc
		case *ast.ValueSpec:
			doc = n.Doc
		case *ast.TypeSpec:
			doc = n.Doc
		}
		if doc != nil {
			docStart[tf.Line(doc.End())+1] = tf.Line(doc.Pos())
		}
		return true
	})
	before, after, trail := map[int][]string{}, map[int][]string{}, map[int][]string{}
	var head, tail []string // detached comments above the package clause, after the last declaration
	for _, c := range f.Comments {
		if c.Head {
			head = append(head, c.Text+"\n")
			continue
		}
		if c.Detached {
			g := 0
			for l := c.Line + strings.Count(c.Text, "\n") + 1; l <= f.Src.LineCount() && g == 0; l++ {
				g = firstGen[l]
			}
			if g == 0 {
				tail = append(tail, "\n"+c.Text)
				continue
			}
			if d, ok := docStart[g]; ok {
				g = d
			}
			in := indent(g)
			before[g] = append(before[g], "\n"+in+strings.ReplaceAll(c.Text, "\n", "\n"+in)+"\n")
			continue
		}
		if g, ok := firstGen[c.Line]; ok && c.Trailing && !inString[g+1] {
			trail[g] = append(trail[g], c.Text)
			continue
		}
		end := c.Line + strings.Count(c.Text, "\n")
		placed := false
		for l := end + 1; l < c.BlockEnd && !placed; l++ {
			if g, ok := firstGen[l]; ok {
				before[g] = append(before[g], indent(g)+c.Text)
				placed = true
			}
		}
		switch {
		case placed:
		case c.After.IsValid() && endGen[c.After] > 0:
			g := endGen[c.After]
			after[g] = append(after[g], indent(startGen[c.After])+c.Text)
		default:
			if g, ok := firstGen[c.BlockStart]; ok {
				after[g] = append(after[g], indent(g)+"\t"+c.Text) // an otherwise empty block
			}
		}
	}
	var out bytes.Buffer
	for _, c := range head {
		out.WriteString(c + "\n")
	}
	for i, ln := range lines {
		g := i + 1
		for _, c := range before[g] {
			out.WriteString(c + "\n")
		}
		if t := trail[g]; len(t) > 0 {
			out.WriteString(strings.TrimSuffix(ln, "\n") + " " + strings.Join(t, " ") + "\n")
		} else {
			out.WriteString(ln)
		}
		for _, c := range after[g] {
			out.WriteString(c + "\n")
		}
	}
	for _, c := range tail {
		out.WriteString(c + "\n")
	}
	formatted, err := format.Source(out.Bytes())
	if err != nil {
		return nil, false
	}
	return formatted, true
}

// stmtMayFail reports whether a statement's own expressions (not nested
// blocks) can panic or otherwise fail at run time.
func stmtMayFail(s ast.Stmt) bool {
	var exprs []ast.Node
	switch s := s.(type) {
	case *ast.AssignStmt:
		for _, e := range s.Lhs {
			exprs = append(exprs, e)
		}
		for _, e := range s.Rhs {
			exprs = append(exprs, e)
		}
	case *ast.ExprStmt:
		exprs = append(exprs, s.X)
	case *ast.ReturnStmt:
		for _, e := range s.Results {
			exprs = append(exprs, e)
		}
	case *ast.IfStmt:
		if s.Init != nil {
			exprs = append(exprs, s.Init)
		}
		exprs = append(exprs, s.Cond)
	case *ast.SwitchStmt:
		if s.Init != nil {
			exprs = append(exprs, s.Init)
		}
		if s.Tag != nil {
			exprs = append(exprs, s.Tag)
		}
	case *ast.ForStmt:
		for _, n := range []ast.Node{s.Init, s.Cond, s.Post} {
			if n != nil && !isNilNode(n) {
				exprs = append(exprs, n)
			}
		}
	case *ast.RangeStmt:
		exprs = append(exprs, s.X)
	case *ast.DeclStmt:
		exprs = append(exprs, s.Decl)
	case *ast.IncDecStmt:
		exprs = append(exprs, s.X)
	case *ast.CaseClause:
		for _, e := range s.List {
			exprs = append(exprs, e)
		}
	case *ast.CommClause:
		// default cannot fail; a receive fails only through its operand.
		if s.Comm == nil {
			return false
		}
		return stmtMayFail(s.Comm)
	case *ast.SelectStmt:
		return false // its clauses are judged on their own lines
	case *ast.SendStmt:
		return true // sending on a closed channel panics
	case *ast.BranchStmt:
		return false
	default:
		return true
	}
	for _, e := range exprs {
		if exprMayFail(e) {
			return true
		}
	}
	return false
}

func isNilNode(n ast.Node) bool {
	switch x := n.(type) {
	case ast.Stmt:
		return x == nil
	case ast.Expr:
		return x == nil
	}
	return false
}

func exprMayFail(n ast.Node) bool {
	fail := false
	ast.Inspect(n, func(x ast.Node) bool {
		switch x := x.(type) {
		case *ast.CallExpr, *ast.IndexExpr, *ast.IndexListExpr, *ast.StarExpr, *ast.SliceExpr, *ast.TypeAssertExpr:
			fail = true
		case *ast.SelectorExpr:
			// Field access may dereference a nil pointer. (Package-qualified
			// names cannot fail, but they are indistinguishable here without
			// type information, so be conservative.)
			fail = true
		case *ast.BinaryExpr:
			if x.Op == token.QUO || x.Op == token.REM {
				fail = true
			}
		case *ast.UnaryExpr:
			if x.Op == token.ARROW {
				fail = true
			}
		case *ast.FuncLit:
			return false
		}
		return !fail
	})
	return fail
}

// preorder lists nodes in depth-first order, skipping parentheses (which
// the printer may insert) and comments.
func preorder(f *ast.File) []ast.Node {
	var out []ast.Node
	ast.Inspect(f, func(n ast.Node) bool {
		switch n.(type) {
		case nil:
			return false
		case *ast.ParenExpr:
			return true
		case *ast.CommentGroup, *ast.Comment:
			return false
		}
		out = append(out, n)
		return true
	})
	return out
}

// Lookup returns the innermost Lyth span covering a generated byte offset,
// and whether the match came from synthetic code.
func (m *SourceMap) Lookup(off int) (source.Span, bool, bool) {
	best := -1
	for i, s := range m.Segments {
		if s.GenStart > off {
			break
		}
		if off < s.GenStart || off >= s.GenEnd && !(off == s.GenEnd && s.GenEnd == s.GenStart) {
			continue
		}
		if best < 0 || s.GenEnd-s.GenStart <= m.Segments[best].GenEnd-m.Segments[best].GenStart {
			best = i
		}
	}
	if best < 0 {
		return source.Span{}, false, false
	}
	return m.Segments[best].Src, m.Segments[best].Synthetic, true
}

// LookupLine returns the Lyth line for a 1-based generated line.
func (m *SourceMap) LookupLine(line int) int {
	for l := line; l >= 1 && l < len(m.LineToSrc); l-- {
		if m.LineToSrc[l] != 0 {
			return m.LineToSrc[l] + (line - l)
		}
	}
	return 0
}

// MarshalJSON writes the sidecar format used by external tools:
// segments are [genStart, genEnd, srcStart, srcEnd, synthetic].
func (m *SourceMap) MarshalJSON() ([]byte, error) {
	type out struct {
		Version   int      `json:"version"`
		Generated string   `json:"generated"`
		Source    string   `json:"source"`
		Segments  [][5]int `json:"segments"`
	}
	o := out{Version: 1, Generated: m.GenName, Source: m.Src.Path}
	for _, s := range m.Segments {
		syn := 0
		if s.Synthetic {
			syn = 1
		}
		o.Segments = append(o.Segments, [5]int{s.GenStart, s.GenEnd, s.Src.Start, s.Src.End, syn})
	}
	return json.Marshal(o)
}

// Describe renders a generated position for verbose diagnostics.
func Describe(name string, line, col int) string {
	var b strings.Builder
	b.WriteString(name)
	if line > 0 {
		b.WriteString(":" + strconv.Itoa(line))
		if col > 0 {
			b.WriteString(":" + strconv.Itoa(col))
		}
	}
	return b.String()
}

// trimBlockEdges removes blank lines that directly follow a line ending in
// "{" or precede a line starting with "}", outside multi-line strings.
func trimBlockEdges(src []byte, f *ast.File, tf *token.File) []byte {
	inString := map[int]bool{}
	ast.Inspect(f, func(n ast.Node) bool {
		if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
			for l := tf.Line(lit.Pos()) + 1; l <= tf.Line(lit.End()); l++ {
				inString[l] = true
			}
		}
		return true
	})
	lines := bytes.SplitAfter(src, []byte("\n"))
	blank := func(i int) bool { return i >= 0 && i < len(lines) && len(bytes.TrimSpace(lines[i])) == 0 }
	var out bytes.Buffer
	for i, ln := range lines {
		if blank(i) && !inString[i+1] {
			afterOpen := i > 0 && bytes.HasSuffix(bytes.TrimRight(lines[i-1], " \t\n"), []byte("{")) && !inString[i]
			beforeClose := i+1 < len(lines) && bytes.HasPrefix(bytes.TrimLeft(lines[i+1], " \t"), []byte("}")) && !inString[i+2]
			if afterOpen || beforeClose {
				continue
			}
		}
		out.Write(ln)
	}
	return out.Bytes()
}

// hoisted reports whether s is glue that runs user code or panics: a call
// spilled into a variable (v, err := f()) or a panic.
func hoisted(s ast.Stmt) bool {
	switch s := s.(type) {
	case *ast.AssignStmt:
		if len(s.Rhs) == 1 {
			_, isCall := s.Rhs[0].(*ast.CallExpr)
			return isCall
		}
	case *ast.ExprStmt:
		if c, ok := s.X.(*ast.CallExpr); ok {
			id, ok := c.Fun.(*ast.Ident)
			return ok && id.Name == "panic"
		}
	}
	return false
}

// placeSentinels moves the placeholder position (1) that lowering gives the
// tokens of chan and struct{} types, so that struct{} prints on one line, to
// the position of the code around them: go/printer reads the lines between
// position 1 and the next node as a gap, and fills it with a blank line (after
// a struct field) or a line break (before a literal's closing brace).
func placeSentinels(root ast.Node) {
	last := token.NoPos
	ast.Inspect(root, func(n ast.Node) bool {
		switch x := n.(type) {
		case nil:
			return false
		case *ast.ChanType:
			if x.Begin == 1 {
				x.Begin, x.Arrow = last, last
			}
		case *ast.StructType:
			if x.Fields != nil && x.Fields.Opening == 1 && last.IsValid() {
				x.Fields.Opening, x.Fields.Closing = last, last
			}
		default:
			if p := n.Pos(); p > 1 {
				last = p
			}
		}
		return true
	})
}

// isDirective reports whether a comment is a directive in gofmt's sense
// (//go:embed, //line): gofmt keeps directives at the end of a doc comment.
func isDirective(c string) bool {
	c, ok := strings.CutPrefix(c, "//")
	if !ok {
		return false
	}
	if strings.HasPrefix(c, "line ") || strings.HasPrefix(c, "extern ") || strings.HasPrefix(c, "export ") {
		return true
	}
	colon := strings.Index(c, ":")
	if colon <= 0 || colon+1 >= len(c) {
		return false
	}
	for i := 0; i <= colon+1; i++ {
		if i == colon {
			continue
		}
		if b := c[i]; !('a' <= b && b <= 'z' || '0' <= b && b <= '9') {
			return false
		}
	}
	return true
}
